import React, { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";

function PaymentPage() {
  const navigate = useNavigate();
  const location = useLocation();

  const [paymentMethod, setPaymentMethod] = useState("");
  const [formData, setFormData] = useState({
    cardNumber: "",
    expiry: "",
    cvv: "",
    upiId: "",
    bankName: "",
    accountNumber: ""
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const validateCardNumber = (num) => /^\d{13,19}$/.test(num.replace(/\D/g, ""));
  const validateExpiry = (exp) => {
    if (!/^\d{2}\/\d{2}$/.test(exp)) return false;
    const [month, year] = exp.split("/").map(Number);
    const now = new Date();
    const currentYear = now.getFullYear() % 100;
    const currentMonth = now.getMonth() + 1;
    return month >= 1 && month <= 12 && (year > currentYear || (year === currentYear && month >= currentMonth));
  };
  const validateCVV = (cvv) => /^\d{3,4}$/.test(cvv);

  const handlePayment = async () => {
    const userEmail = localStorage.getItem("userEmail");
    const bookingDetails = location.state;

    if (!userEmail) {
      alert("User email not found in localStorage!");
      return;
    }
    if (!bookingDetails) {
      alert("Booking details are missing!");
      return;
    }

    // Payment validation
    if (paymentMethod === "card") {
      if (!validateCardNumber(formData.cardNumber)) return alert("Invalid card number.");
      if (!validateExpiry(formData.expiry)) return alert("Invalid expiry date.");
      if (!validateCVV(formData.cvv)) return alert("Invalid CVV.");
    } else if (paymentMethod === "upi") {
      if (!formData.upiId.includes("@")) return alert("Invalid UPI ID.");
    } else if (paymentMethod === "netbanking") {
      if (!formData.bankName || !formData.accountNumber) return alert("Fill Net Banking details.");
    } else {
      return alert("Select a payment method.");
    }

    try {
      console.log("Sending email to:", userEmail);
      console.log("Booking details:", bookingDetails);

      const response = await fetch("http://localhost:8081/api/send-email", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: userEmail, bookingDetails }),
      });

      const result = await response.text();
      alert(result); // Shows email success/failure
      if (result.includes("success")) {
        navigate("/success", { state: bookingDetails });
      }
    } catch (err) {
      console.error(err);
      alert("Failed to send email: " + err.message);
    }
  };

  // ... keep the rest of your PaymentPage JSX as-is (inputs, buttons, styles)
}

export default PaymentPage;
